    if (ol_pre(l, "  imm r") == 0) return 0 - 1;
    p = ol_s[l] + 6; e = ol_e[l]; q = p;
    while (q < e && out[q] != 44) q = q + 1;
    k = ol_reg(p, q);
    if (k < 0 || q + 2 >= e || out[q + 1] != 32) return 0 - 1;
    q = q + 2; v = 0;
    if (e - q > 18) return 0 - 1;
    while (q < e) { if (isdi(out[q] & 255) == 0) return 0 - 1; v = v * 10 + out[q] - 48; q = q + 1; }
