            if (out[p] - 48 != a || out[p + 1] != 43 || out[p + 2] != 48 || out[p + 3] != 93) return 0;
            if (out[p + 4] != 44 || out[p + 5] != 32 || out[p + 6] != 114) return 0;
            q = p + 7; v = 0;
            if (q >= e || isdi(out[q] & 255) == 0) return 0;
            while (q < e && isdi(out[q] & 255)) { v = v * 10 + out[q] - 48; q = q + 1; }
            if (v == a || v == 2) return 0;
